from odoo import api, fields, models
from odoo.tools import float_compare


class PurchaseOrder(models.Model):
    _inherit = 'purchase.order'

    # Technical names generated by Odoo Studio, kept so the data is reused.
    x_studio_reference = fields.Char(string='Reference', related='requisition_id.reference')
    x_studio_reference_1 = fields.Char(string='Reference', related='requisition_id.reference')

    # The core rate is recomputed from the currency table; Lotoi needs to fix it
    # for a single order without touching the general rate.
    lotoi_manual_currency_rate = fields.Boolean(string='Manual exchange rate', copy=False)
    lotoi_manual_rate_currency_id = fields.Many2one('res.currency', copy=False)
    lotoi_exchange_rate = fields.Float(
        string='Exchange rate',
        digits=(16, 4),
        compute='_compute_lotoi_exchange_rate',
        inverse='_inverse_lotoi_exchange_rate',
        help='Company currency units per one unit of the order currency. '
             'Changing it only affects this order and the bills made from it.',
    )

    def _lotoi_has_manual_rate(self):
        self.ensure_one()
        return self.lotoi_manual_currency_rate and self.lotoi_manual_rate_currency_id == self.currency_id

    def _lotoi_auto_currency_rate(self):
        self.ensure_one()
        return self.env['res.currency']._get_conversion_rate(
            from_currency=self.company_id.currency_id,
            to_currency=self.currency_id,
            company=self.company_id,
            date=(self.date_order or fields.Datetime.now()).date(),
        )

    @api.depends('currency_rate')
    def _compute_lotoi_exchange_rate(self):
        for order in self:
            order.lotoi_exchange_rate = 1 / order.currency_rate if order.currency_rate else 0.0

    def _inverse_lotoi_exchange_rate(self):
        for order in self:
            if order.lotoi_exchange_rate <= 0:
                continue
            auto_rate = order._lotoi_auto_currency_rate()
            # The form sends back the displayed (rounded) rate even when the user did not change it.
            if auto_rate and float_compare(order.lotoi_exchange_rate, 1 / auto_rate, precision_digits=4) == 0:
                if order.lotoi_manual_currency_rate:
                    order.lotoi_manual_currency_rate = False
                continue
            order.write({
                'currency_rate': 1 / order.lotoi_exchange_rate,
                'lotoi_manual_currency_rate': True,
                'lotoi_manual_rate_currency_id': order.currency_id.id,
            })

    @api.onchange('currency_id')
    def _onchange_currency_id_lotoi_reset_rate(self):
        self.lotoi_manual_currency_rate = False

    @api.depends('lotoi_manual_currency_rate', 'lotoi_manual_rate_currency_id')
    def _compute_currency_rate(self):
        manual = self.filtered(lambda order: order._lotoi_has_manual_rate())
        super(PurchaseOrder, self - manual)._compute_currency_rate()

    @api.depends('currency_rate')
    def _amount_all(self):
        return super()._amount_all()

    def _prepare_invoice(self):
        invoice_vals = super()._prepare_invoice()
        if self._lotoi_has_manual_rate():
            invoice_vals.update({
                'invoice_currency_rate': self.currency_rate,
                'lotoi_fixed_currency_rate': True,
            })
        return invoice_vals


class PurchaseOrderLine(models.Model):
    _inherit = 'purchase.order.line'

    x_studio_many2one_field_4sr_1j4ks5e81 = fields.Many2one('uom.uom', string='Unidades')
